  "settings.copilotCompletion": "Completamento automatico GitHub Copilot",
  "settings.copilotCompletionHelp": "Offre GitHub Copilot come secondo provider di completamento automatico per i file di codice. Ollama resta il predefinito; non viene inviato nulla finché un progetto non acconsente qui sotto.",
  "settings.copilotCloudNotice": "Copilot è un servizio cloud. Per un progetto che lo accetta, il contenuto dei file di codice che modifichi lascia questa macchina, e il suo language server può leggere il resto della cartella del progetto. Gira nella sandbox: sola lettura, solo quel progetto, nessun accesso alla tua cartella home o ad altre credenziali.",
