  "settings.themeVars": "Colori del tema",
  "settings.themeVars.help": "Ricolora il tema attivo una variabile alla volta — superfici, testo, bordi, l’accento, tinte di stato — in una finestra a parte, insieme allo stile degli angoli. Le sostituzioni valgono su ogni tema, non solo su questo.",
  "settings.themeVars.open": "Personalizza…",
  "theme.title": "Colori del tema",
  "theme.intro": "Ogni valore qui sostituisce il token del tema attivo — su questo tema e su tutti gli altri — finché non lo ripristini. I colori sono #rrggbb, oppure #rrggbbaa dove un valore deve restare traslucido.",
  "theme.reset": "Ripristina tutto",
  "theme.resetOne": "Torna al valore del tema",
  "theme.overridden": "{n} sostituiti",
  "theme.none": "Nessuna sostituzione",
  "theme.presets": "Temi salvati",
  "theme.presets.help":
    "Mette da parte l'intero aspetto sotto un nome — tema di base, accento, ogni colore modificato qui e lo stile degli angoli — per riprenderlo più tardi o tenere due palette affiancate.",
  "theme.presets.name": "Dai un nome a questo aspetto",
  "theme.presets.save": "Salva l'attuale",
  "theme.presets.replace": "Sostituisce il tema salvato con lo stesso nome",
  "theme.presets.full": "L'elenco è pieno — {n} temi salvati. Eliminane uno prima.",
  "theme.presets.none": "Non c'è ancora nulla di salvato. Dai un nome all'aspetto attuale e comparirà qui.",
  "theme.presets.load": "Carica",
  "theme.presets.loadHelp": "Applica questo aspetto — tema di base, accento, colori e angoli",
  "theme.presets.update": "Sovrascrivi con l'aspetto attuale",
  "theme.presets.delete": "Elimina",
  "theme.presets.confirm": "Eliminare?",
  "theme.presets.meta": "{theme} · {n} colori",
  "theme.presets.metaPlain": "{theme} · colori del tema invariati",
  "theme.palette": "Colori di questo tema",
  "theme.palette.pick": "Scegli tra i colori che questo tema già usa",
  "theme.group.surfaces": "Superfici",
  "theme.group.surfaces.help": "La finestra, i suoi pannelli e le intestazioni che vi stanno sopra — le barre delle schede delle sottofinestre e le intestazioni del pannello file, che condividono una seconda superficie. La barra superiore dell’app segue --bg-header da qui finché non le dai un riempimento tutto suo in «Barra superiore», più sotto.",
  "theme.group.topframe": "Barra superiore",
  "theme.group.topframe.help": "La barra del titolo di {app} — la striscia che porta l’orologio, le pill dei progetti e i pulsanti della finestra. La compongono tre strati: un riempimento, un velo d’accento sopra di esso e la cucitura sotto, che dice dove finisce il cromo dell’app e comincia il suo contenuto. Ognuno segue un token condiviso finché non lo fissi, così la barra si può ritonalizzare senza che l’accento si muova nel resto della finestra. I tre livelli di testo qui sotto sono rimappati per l’intero sottoalbero della barra, così un valore muove in un colpo ogni sua etichetta — i menu che ne escono mantengono l’inchiostro del tema.",
  "theme.group.subwindow": "Sottofinestre",
  "theme.group.subwindow.help": "L’intestazione propria di una sottofinestra — la barra delle schede sopra ogni riquadro — più i due segni che dicono quale sottofinestra ha il fuoco. La barra condivide la seconda superficie di cromo dell’app con tutte le intestazioni del pannello file, e i suoi segni leggono l’accento nudo: niente di tutto ciò si poteva muovere da solo. Fissa qui un livello di testo e l’intera barra lo segue: etichette delle schede, maniglia, frecce, chip.",
  "theme.group.sidepanel": "Pannello laterale",
  "theme.group.sidepanel.help": "Il pannello dei file che entra dal bordo, per conto suo. Ogni valore qui segue il token condiviso che leggerebbe altrimenti, così il pannello si stacca dal resto della finestra solo quando ne fissi uno — e le sue intestazioni si muovono senza portarsi dietro le barre delle schede delle sottofinestre.",
  "theme.group.alerts": "Striscia degli avvisi",
  "theme.group.alerts.help": "Il gruppo avvisi sotto l’albero dei file — posta urgente, i prossimi appuntamenti, le carte in scadenza. Il suo aspetto deriva dall’accento, dallo sfondo della finestra e dalle tinte di stato; questi valori sono quella derivazione, così la striscia si può ritingere senza muovere ciò da cui prende in prestito.",
  "theme.group.text": "Testo",
  "theme.group.text.help": "I tre livelli di testo, dal più chiaro al più smorzato.",
  "theme.group.borders": "Bordi",
  "theme.group.borders.help": "Separatori e contorni — quello visibile e quello appena accennato.",
  "theme.group.accent": "Accento",
  "theme.group.accent.help": "La tinta propria del tema e i suoi stati. L’accento in sé è un’impostazione a parte, valida su tutti i temi: scegli una tinta proposta o una qualsiasi altra, e il resto ne deriva finché non viene fissato qui.",
  "theme.group.controls": "Controlli",
  "theme.group.controls.help": "Campi e pulsanti, più i veli neutri di hover e incasso che poggiano su qualsiasi superficie.",
  "theme.group.status": "Stato",
  "theme.group.status.help": "Successo, avviso e pericolo, con accanto le tinte degli stati delle attività.",
  "theme.group.pills": "Pill di progetto",
  "theme.group.pills.help": "La pill di progetto attiva e quella sotto il puntatore nella barra superiore.",
  "theme.group.window": "Pulsanti finestra",
  "theme.group.window.help": "Chiudi, riduci a icona e ingrandisci.",
  "theme.group.activity": "Mappa di attività",
  "theme.group.activity.help": "La scala a cinque passi dietro il calendario di attività del progetto, da vuoto al più intenso.",
  "theme.group.other": "Tutto il resto",
  "theme.group.other.help": "Logo, cursore della barra di scorrimento e i riempimenti smerigliati con cui i due temi di vetro dipingono il proprio cromo.",
