  "settings.claudeRemote": "Controllo remoto di Claude",
  "mcpSecurity.title": "Accesso delle sessioni MCP",
  "mcpSecurity.help": "I permessi valgono solo per questa sessione in corso. Le nuove sessioni root mantengono i valori predefiniti; i lettori di posta iniziano solo con la posta. Disattivare la scrittura dà accesso in sola lettura. I dati condivisi con un agente con accesso alla rete possono lasciare questo computer. Le scritture limitate di calendario e bacheca richiedono sempre una revisione. La revoca è definitiva per la scheda: il suo agente viene rifiutato da quel momento, e solo riaprire la scheda consegna un nuovo token.",
  "mcpSecurity.refresh": "Aggiorna",
  "mcpSecurity.empty": "Nessuna sessione MCP attiva.",
  "mcpSecurity.headless": "Le schede che {app} Mobile ha avviato senza finestre aperte ricevono gli strumenti di pianificazione, push e aiuto dal servizio in background di Mobile, non da questa finestra. Le loro sessioni non sono elencate qui. Terminano quando la scheda viene chiusa o il servizio si ferma. Le loro richieste di push e release vengono rifiutate finché la scheda non viene riavviata da questa finestra.",
  "mcpSecurity.write": "Consenti modifiche a calendari, bacheche e bozze",
  "mcpSecurity.revoke": "Revoca accesso",
  "mcpSecurity.all": "Tutti, comprese le voci future",
  "mcpSecurity.calendars": "Calendari visibili",
  "mcpSecurity.projects": "Progetti e schede visibili",
  "mcpSecurity.accounts": "Account di posta visibili (resta necessario il consenso dell’account)",
  "mcpSecurity.unassigned": "Schede senza progetto",
  "mcpSecurity.family.calendar": "Strumenti del calendario",
  "mcpSecurity.family.board": "Strumenti della bacheca",
  "mcpSecurity.family.projects": "Riepiloghi dei progetti",
  "mcpSecurity.family.mail": "Strumenti di posta",
  "mcpSecurity.agent": "Agente radice",
  "mcpSecurity.local_model": "Modello locale",
  "mcpSecurity.reader": "Lettore di posta",
  "mcpSecurity.audit": "Attività MCP recente",
  "mcpSecurity.auditHelp": "Gli ultimi 50 di al massimo 500 record tenuti in memoria per questa esecuzione. I record contengono sessione, strumento, decisione, tempi e una categoria fissa di motivo (per una sessione di programmazione anche la destinazione), senza credenziali, argomenti o corpi dei messaggi. Le richieste rifiutate prima dell'autenticazione compaiono come «Nessuna sessione», con un limite proprio. Un record appartiene al token della scheda: tutto ciò che l'agente avvia in quella scheda (un hook, uno script, una build) eredita il token e può chiamare gli strumenti come quella scheda, quindi un record è della scheda, non necessariamente una chiamata dell'agente stesso.",
  "mcpSecurity.time": "Ora",
  "mcpSecurity.caller": "Sessione",
