  "mcpSecurity.revokeTitle": "Revocare l'accesso MCP di questa scheda?",
  "mcpSecurity.revokeBody": "«{tab}» perde definitivamente gli strumenti di {app}: il suo agente viene rifiutato da ora, e solo riaprire la scheda consegna un nuovo token.",
