  "rootReview.create": "Crea",
  "rootReview.setting": "Esamina le scritture degli agenti root",
  "rootReview.levelAll": "Tutte le scritture (predefinito)",
  "rootReview.levelDestructive": "Scritture distruttive; le altre si applicano con possibilità di annullamento",
  "rootReview.levelOff": "Disattivato — applica subito le modifiche",
  "rootReview.settingHelp": "Esamina le proposte del calendario e della bacheca nella console root. Si applica subito alle successive chiamate degli strumenti. Le proposte esistenti richiedono ancora una decisione. Questo protegge le scritture; gli agenti possono comunque divulgare i dati che hanno letto.",
  "settings.rootMcp": "Strumenti di {app} (MCP) per gli agenti della console root",
  "settings.rootMcpHelp": "Gli agenti della console root (Ctrl+Maiusc+R) con il chip MCP del menu Modelli e agenti ricevono gli strumenti di {app}: progetti, calendario e bacheca delle attività. Disattivato: i nuovi agenti non ricevono nulla e quelli già in esecuzione vengono rifiutati, senza riavvio. Gli agenti di un progetto non li ricevono mai.",
  "settings.rootMcpLocalOnly": "Solo i modelli locali ricevono questi strumenti",
  "settings.rootMcpLocalOnlyHelp": "Riserva gli strumenti di {app} alle schede dei modelli locali (quelle con il chip MCP del menu «Modelli e agenti»). Claude, Codex e ogni altro agente cloud non ricevono nulla, e quelli già in esecuzione vengono rifiutati senza riavvio: così calendario e bacheca non raggiungono mai un modello ospitato tramite questi strumenti.",
  "settings.rootMcpMail": "Gli agenti ricevono gli strumenti di posta di {app}",
  "settings.rootMcpMailLocalOnly": "Solo i modelli locali ottengono gli strumenti di posta",
  "settings.rootMcpMailLocalOnlyHelp": "Riserva gli strumenti di posta alle schede dei modelli locali (quelle con il chip MCP del menu Modelli e agenti); gli agenti cloud mantengono gli strumenti di calendario, bacheca e progetti. A Claude, Codex e ogni altro agente cloud non viene offerto alcuno strumento di posta, quelli già in esecuzione li perdono senza riavvio e un agente lettore confinato viene rifiutato: nessuna bozza né messaggio raggiunge così un modello ospitato tramite questi strumenti.",
  "settings.rootMcpMailLocalRead": "I modelli locali possono leggere le email che condividi",
  "settings.rootMcpMailLocalReadHelp": "Permette a una scheda con modello locale (quelle con il chip MCP del menu Modelli e agenti) di leggere la posta degli account che hai aperto agli agenti: solo i messaggi che hai condiviso, anche quando un account è aperto per intero. La lettura viene rifiutata a meno che l'host Ollama con cui la scheda è stata aperta sia questa macchina: il controllo è su quell'host, registrato all'avvio della scheda, non sull'impostazione attuale, così la posta resta dove gira il modello. Una scheda del genere ha solo gli strumenti di {app}, senza shell né web; una volta letta la posta, ogni modifica al calendario o alla bacheca attende la tua approvazione — in quella scheda e in ogni sua esecuzione successiva — e le sue bozze sono contrassegnate come scritte da un agente che legge la posta. Non invia mai. Una mail costruita ad arte può ancora orientare ciò che il modello scrive, quindi leggi le sue bozze e proposte prima di accettarle.",
  "settings.rootMcpMailHelp": "Disattivato per impostazione predefinita e separato dall'interruttore qui sopra: attivare gli strumenti di {app} non porta mai con sé la posta. Attivo, un agente root può scrivere bozze (mai inviare, e mai leggere a meno che l'interruttore dei modelli locali qui sotto permetta a un modello locale di leggere le email che condividi), e un agente lettore confinato in un progetto VM «lettore di posta» può leggere gli account che gli hai aperto. Disattivato, non viene offerto alcuno strumento di posta, gli agenti già in esecuzione vengono rifiutati senza riavvio e gli interruttori per account non hanno effetto.",
  "settings.headlessRemote": "Connessioni remote headless",
  "settings.persistLocal": "Sessioni locali persistenti (tmux)",
  "settings.remoteFeatures": "Funzioni remote",
