  "settings.vmCheckFailed": "Impossibile verificare i prerequisiti delle VM. Riapri questa pagina per riprovare.",
  "settings.vpnEnabled": "Controllo del tunnel OpenVPN",
  "settings.machinesEnabled": "Macchine remote globali",
  "settings.energySaver": "Risparmio energetico",
  "settings.fastMode": "Modalità rapida",
  "energy.off": "Disattivato",
  "energy.battery": "A batteria",
  "energy.always": "Sempre",
  "settings.debug": "Modalità debug",
  "settings.experimental": "Sperimentale",
  "settings.terminalWebgl": "Renderer WebGL del terminale",
  "settings.terminalWebglHelp": "Disegna i terminali con un atlante di glifi su GPU (il livello veloce — quello di VS Code) invece del renderer canvas. Usa lo stesso percorso del driver GPU difettoso su alcune macchine: in caso di sfarfallio, testo mancante o finestra bloccata, disattivalo. Un terminale il cui contesto WebGL fallisce torna da solo al renderer canvas. Si applica subito anche ai terminali già aperti.",
  "settings.mdGraph": "Grafo dei link Markdown",
  "settings.mdGraphHelp": "Aggiunge una modalità Grafo al visualizzatore markdown: una mappa cliccabile dei file collegati da questo documento, esplorata link per link a partire dal file in vista (le destinazioni markdown vengono seguite, ogni altro file è una foglia). Clicca un nodo per aprire quel file; la mappa viene costruita una volta per consultazione, mai in background.",
  "settings.pythonRunDebug": "Esegui/Debug Python nel visualizzatore di codice",
  "settings.mailClient": "Client di posta",
  "settings.mailClientHelp": "Mette un pulsante Posta nell'intestazione che apre un client IMAP/SMTP, con un proprio indice locale, come sovrapposizione sull'intera finestra — la posta è tua, non di un progetto, quindi non esiste una scheda Posta. Un pallino rosso sul pulsante conta la posta non letta in arrivo. Disattivandolo il pulsante sparisce; gli account e la posta scaricata restano intatti.",
  "settings.mailCheckInterval": "Controlla la nuova posta",
  "settings.mailCheckIntervalHelp": "Con quale frequenza {app} controlla i tuoi account da solo: ogni 5 minuti, salvo tua indicazione diversa. Impostato su Mai, la posta viene scaricata solo quando premi Controlla posta, e il pallino rosso può comparire solo subito dopo.",
  "settings.mailCheckNever": "Mai — solo su richiesta",
  "settings.mailCheckMinutes": "Ogni {count} minuti",
  "settings.webBrowser": "Browser integrato",
  "settings.webBrowserHelp1": "Aggiunge una scheda Browser. Le pagine si aprono in",
  "settings.webBrowserHelp2": "— solo testo e immagini, senza script, senza moduli e senza accesso. Una pagina reale gira in una finestra separata, a un clic deliberato di distanza, e solo dove questa build può ospitarla.",
  "settings.browser": "Browser",
  "settings.browserHome": "Indirizzo iniziale",
  "settings.browserHomePlaceholder": "(pagina iniziale)",
  "settings.browserHomeHelp": "Dove si apre una nuova scheda del browser. Lascialo vuoto e una nuova scheda si apre sulla sua pagina iniziale: non va in rete finché non glielo chiedi.",
  "settings.browserSearch": "Indirizzo di ricerca",
  "settings.browserSearchHelp": "Cosa fa la barra degli indirizzi con un testo che non è un indirizzo web: %s viene sostituito da ciò che hai digitato. Svuota il campo e quel testo viene semplicemente rifiutato, invece di finire a un motore di ricerca.",
  "settings.browserLinkTarget": "Apri i link in",
  "settings.browserLinkTargetExternal": "Il tuo browser",
  "settings.browserLinkTargetInApp": "Il lettore di {app}",
  "settings.browserLinkTargetAsk": "Chiedi ogni volta",
  "settings.browserLinkTargetHelp": "Il tuo browser è l'impostazione predefinita: ha i tuoi accessi, le tue estensioni e il tuo gestore di password. I link che arrivano dalla posta, dall'output di un terminale o dalla risposta di un agente si aprono sempre in modalità lettura, qualunque cosa dica questa impostazione: lì la destinazione non l'hai scelta tu. La tua scelta viene registrata, ma le superfici di link di {app} non la consultano ancora: per ora ogni link va comunque nel tuo browser.",
  "settings.browserRestoreNavigate": "Ricarica le pagine aperte all'avvio",
  "settings.browserRestoreNavigateHelp": "Disattivato di default. Con l'opzione disattivata una scheda ripristinata mostra l'indirizzo su cui era e ti aspetta: riaprire una finestra non è una richiesta di andare in rete.",
  "settings.browserLivePages": "Consenti pagine live",
  "settings.browserLivePagesHelp": "Disattivato di default, anche nelle build di debug. La modalità lettura mostra il testo di una pagina senza alcuno script. Una pagina live esegue la pagina web reale in una finestra rinforzata separata, il che significa anche che può raggiungere servizi in esecuzione su questa macchina, come un server di modelli locale o un notebook, e questo non è impedibile dall'interno di {app}. Attivalo solo se ti serve.",
  "settings.resourceMonitor": "Monitoraggio risorse",
  "settings.showCpu": "Mostra utilizzo CPU",
  "settings.showRam": "Mostra utilizzo RAM",
  "settings.showGpu": "Mostra utilizzo GPU",
  "settings.clock": "Orologio",
  "settings.showClockSeconds": "Mostra i secondi nell'orologio dell'intestazione",

  "settings.calendar": "Calendario",
  "settings.calendarGlobalApp": "Calendario nell'intestazione",
  "settings.calendarGlobalAppHelp": "Aggiunge un pulsante calendario all'intestazione che apre il calendario come sovrapposizione sull'intera finestra, ovunque tu sia: il tuo calendario non appartiene al progetto che ti capita di guardare. Un pallino rosso conta gli eventi rimasti oggi e si svuota da solo con il passare della giornata.",
