  "mobile.title": "{app} Mobile",
  "mobile.mailWrites": "Posta dal telefono",
  "mobile.mailRead": "Leggere la posta sul telefono",
  "mobile.mailReadHelp": "Un telefono abbinato può elencare i tuoi account e le cartelle di posta e aprire i messaggi. Disattivato, la vista posta del telefono viene rifiutata del tutto, compresi segnare e rispondere.",
  "mobile.mailActions": "Segnare come letto e mettere la stella dal telefono",
  "mobile.mailActionsHelp": "Un telefono abbinato può segnare un messaggio come letto o non letto e mettere o togliere la stella. Il desktop applica il flag tramite la propria sessione di posta e risponde con l'elenco aggiornato. Eliminare e spostare restano sul desktop, dove si possono annullare.",
  "mobile.mailReply": "Rispondere dal telefono",
  "mobile.mailReplyHelp": "Un telefono abbinato può inviare una risposta in testo semplice a un messaggio che sta leggendo. Il telefono fornisce solo il testo: destinatario, oggetto e thread derivano dal messaggio originale, quindi un telefono può rispondere solo a chi ti ha già scritto. Niente nuove mail, niente allegati, niente firma o cifratura. Un telefono smarrito con questa opzione attiva può inviare posta a tuo nome finché non la revochi.",
  "mobile.settingsHelp": "Accesso privato ai terminali di progetto tramite Tailscale Serve. L'host ascolta solo sul loopback e ogni browser deve essere abbinato. Resta attivo finché {app} è aperto: avviato con l'app, fermato alla sua chiusura.",
  "mobile.healthOffTitle": "Mobile è spento",
  "mobile.healthOffDetail": "Al momento non è pubblicato alcun host {app} Mobile.",
  "mobile.healthStoppedTitle": "L'host è fermo",
  "mobile.healthStoppedDetail": "Mobile è attivo nelle impostazioni ma non sta servendo; avvialo solo dopo aver controllato la mappatura Serve privata.",
  "mobile.healthServeTitle": "La mappatura Serve richiede attenzione",
  "mobile.healthServeDetail": "{app} al momento non riesce a verificare la sua esatta mappatura HTTPS privata sul loopback.",
  "mobile.healthGoodTitle": "Pubblicazione privata verificata",
  "mobile.healthGoodDetail": "L'host è solo loopback e la rotta Tailscale Serve configurata è HTTPS privato.",
  "mobile.lockdownNow": "Blocca adesso",
  "mobile.lockdownTitle": "Revoca ogni dispositivo abbinato e ferma l'host",
  "mobile.lockdownTitleStopped": "L'host è già fermo",
  "mobile.lockdownConfirm": "Bloccare {app} Mobile adesso? Questo revoca immediatamente ogni telefono abbinato, chiude le loro connessioni ai terminali e ferma l'host Mobile. Ogni telefono dovrà abbinarsi di nuovo.",
  "mobile.lockdownPartial": "Il blocco è stato completato solo in parte: {reason}",
  "mobile.scopeHelp": "Questo controlla la forma di pubblicazione di {app}, non le ACL del tuo tailnet, la MFA dell'account, Tailnet Lock o il blocco schermo del telefono. Configurali in Tailscale e sul telefono.",
  "mobile.phoneInstallTitle": "Installa {app} Mobile sul tuo telefono",
  "mobile.phoneInstallHelp": "Verifica la mappatura Tailscale Serve privata e poi mostra l'URL attendibile e un codice QR scansionabile in un terminale root. Non attiva Mobile e non cambia la tua configurazione di Tailscale.",
  "mobile.phoneInstallButton": "Mostra QR di installazione",
  "mobile.phoneInstallTab": "Installa {app} Mobile sul telefono",
  "mobile.phoneInstallToast": "Il passaggio di installazione al telefono è in esecuzione nel terminale root",
  "mobile.phoneInstallError": "Impossibile aprire il passaggio di installazione al telefono: {reason}",
  "mobile.guideSummary": "Configura Tailscale Serve",
  "mobile.windowsTerminalsNote": "Su Windows il telefono non può aprire i terminali né le schede degli agenti di questo computer: si collegano tramite tmux, che Windows non ha.",
  "mobile.guideIntro": "Fallo su questo computer prima di attivare {app} Mobile. Installa Tailscale e accedi qui, poi installalo e accedi allo stesso tailnet sul telefono o tablet che userà Mobile.",
  "mobile.guideStep1a": "In un terminale di questo computer, ispeziona la pubblicazione esistente con",
  "mobile.guideStep1b": ". {app} Mobile ha bisogno del gestore HTTPS / (root), quindi non sostituire un gestore root esistente a meno che tu non voglia davvero spostare quel servizio.",
  "mobile.guideStep2a": "Configura il proxy inverso privato e persistente. Usa Serve — non Funnel:",
  "mobile.guideStep2b": "Se Tailscale chiede un'approvazione o la configurazione HTTPS, completala nel browser che apre.",
  "mobile.guideStep3a": "Esegui",
  "mobile.guideStep3b": "di nuovo, poi usa",
  "mobile.guideStep3c": "qui sotto. {app} compila il nome del computer, la porta loopback e l'origine verificata dalla mappatura root privata.",
  "mobile.guideStep4a": "Attiva {app} Mobile. {app} verifica che il gestore root dell'origine inoltri esattamente a",
  "mobile.guideStep4b": "; usa",
  "mobile.guideStep4c": "se hai cambiato Tailscale in un altro terminale.",
  "mobile.guideStep5": "Attiva i progetti locali che vuoi esporre, crea un codice di abbinamento, poi apri l'origine verificata sul telefono o tablet e inserisci quel codice.",
  "mobile.guideOutro": "L'indirizzo è raggiungibile solo dai dispositivi ammessi nel tuo tailnet, e Mobile richiede comunque il proprio abbinamento dei dispositivi. Non usare Tailscale Funnel: rende pubblico il servizio e {app} si rifiuterà di avviarsi.",
