  "mobile.setupStep5Title": "Scegli cosa può aprire il telefono",
  "mobile.setupStep5Body": "In «Accesso per progetto», nelle stesse impostazioni, attiva i progetti e le box che il telefono può aprire. Tutto è disattivato finché non lo attivi.",
  "mobile.setupStep6Title": "Abbina il telefono",
  "mobile.setupStep6Body": "Premi «Mostra QR di installazione» e scansionalo con il telefono, poi crea un codice di abbinamento e inseriscilo lì. Un codice è valido cinque minuti.",
  "mobile.setupOpenSettings": "Apri le impostazioni Mobile",
  "settings.usageStats": "Statistiche di utilizzo",
  "settings.pdfMarkup": "Annotazione PDF",
  "settings.pdfMarkupHelp": "Ciò che Annota del visore PDF invia all’agente. Salvato su questo computer; il telefono ha il suo (Home → ⚙ Questo dispositivo → Prompt di annotazione).",
  "settings.pdfMarkupInstruction": "Prompt di annotazione",
  "settings.pdfMarkupInstructionHelp": "Segue il file, la copia annotata, i livelli e le tue note a ogni invio. Con «Applica le annotazioni direttamente» attivo, per impostazione predefinita l’agente fa le modifiche e ricompila il PDF; altrimenti — o dove non si può tenere un annullamento — elenca le modifiche e non modifica nulla finché non lo dici.",
  "settings.pdfMarkupApply": "Prompt «Applica queste modifiche»",
  "settings.pdfMarkupApplyHelp": "Inviato dal pulsante Applica queste modifiche quando l’agente ha elencato ciò che chiedono le tue annotazioni.",
  "settings.pdfMarkupAutoReload": "Ricarica il PDF sotto le tue annotazioni quando cambia",
  "settings.pdfMarkupAutoReloadHelp": "Quando l’agente ricompila un PDF che stai annotando, le nuove pagine compaiono da sole sotto le tue annotazioni. Disattivato: la barra delle annotazioni offre Ricarica PDF.",
  "settings.pdfMarkupSubagents": "Affida ogni invio a un nuovo subagente",
  "settings.pdfMarkupSubagentsHelp": "Ogni invio chiede all’agente di affidare il giro a un nuovo subagente suo e di tornare subito libero, così il giro successivo parte senza attese — i giri procedono in parallelo. Per agenti che possono avviare subagenti (Claude Code); uno che non può fa il giro da sé.",
  "settings.pdfMarkupDirect": "Applica le annotazioni direttamente",
  "settings.pdfMarkupDirectHelp": "All’invio l’agente fa subito le modifiche; quando ha finito, Annulla riporta com’era ogni file cambiato dal giro — e rifiuta piuttosto che sovrascrivere ciò che è cambiato da allora. Dove non si può tenere un annullamento (non è un repository git, troppi file non tracciati, …), o con questo spento, l’agente elenca prima le modifiche e «Applica queste modifiche» gliele fa fare.",
  "settings.pdfMarkupReset": "Usa il predefinito",
  "markup.ask.label": "Domande sui tuoi segni",
  "markup.ask.help": "Quanto spesso l’agente ti chiede di un segno prima di elencare le modifiche. Aggiunto dopo il prompt di markup a ogni invio.",
  "markup.ask.stop0": "Chiedi sempre",
  "markup.ask.stop1": "Chiedi spesso",
  "markup.ask.stop2": "Chiedi se incerto",
  "markup.ask.stop3": "Chiedi di rado",
  "markup.ask.stop4": "Non chiedere mai",
  "markup.ask.hint0": "Una domanda per ogni segno prima che conti come modifica.",
  "markup.ask.hint1": "Chiede appena un segno lascia una scelta.",
  "markup.ask.hint2": "Chiede solo per segni illeggibili o scelte reali; per il resto prende la lettura ovvia.",
  "markup.ask.hint3": "Chiede solo se non può agire su un segno senza la tua risposta.",
  "markup.ask.hint4": "Decide da sé ogni segno incerto ed elenca cosa ha deciso.",
  "settings.dailyRecap": "Mostra il riepilogo all'inizio di ogni giorno",
