  "updates.help": "{app} controlla la pagina delle release GitHub del progetto — solo quando glielo chiedi. Nulla viene scaricato prima di un clic, e il riavvio resta tuo.",
  "brand.tagline": "Una scheda per ogni progetto. Una scheda per tutto ciò che contiene.",
