  "updates.legacyTitle": "Nomi di prima del cambio di nome",
  "updates.legacyHelp": "{app} ha cambiato nome. Ciò che una versione precedente ha salvato con il vecchio nome viene trasferito, e ogni volta che qualcosa si trova ancora solo con il vecchio nome viene contato qui. Quando questo elenco resta vuoto su tutti i tuoi computer, il vecchio nome non serve più da nessuna parte.",
