  "updates.savedTo": "Salvato in {path}",
  "updates.openReleasePage": "Apri la pagina della release",
  "updates.installAppimageHelp": "Installare sostituisce l’AppImage in esecuzione. Le tue schede e i terminali restano aperti — riavvia {app} quando ti fa comodo.",
  "updates.installNsisHelp": "Installare avvia il programma di installazione di Windows, che prima propone di chiudere {app}.",
  "updates.installDmgHelp": "Installare apre l’immagine disco — trascina {app} in Applicazioni da lì.",
  "updates.installManualHelp": "Questa copia di {app} è stata installata da un gestore di pacchetti, quindi il download resta a te da installare.",
  "settings.energyUnavailable": "Stato energia non disponibile — trattato come a corrente (inattivo).",
  "settings.energyActiveAlways": "Attualmente attivo — sempre acceso.",
  "settings.energyActiveBattery": "Attualmente attivo — funziona a batteria.",
  "settings.energyOff": "Disattivato — non limita mai le prestazioni.",
  "settings.energyInactive": "Inattivo — a corrente.",
  "settings.claudeRemoteHelp1": "Avvia schede agente Claude con",
  "settings.claudeRemoteHelp2": "così puoi monitorarle e guidarle dall'app o dal web di Claude. Richiede l'accesso con un abbonamento Claude (non una chiave API); solo Claude lo supporta.",
  "settings.headlessRemoteHelp": "Se attivo (predefinito), {app} stabilisce le connessioni SSH/OpenVPN in background, gestendo la password in modo transitorio. Disattivalo per aprire invece ogni connessione come terminale interattivo nella root di {app} — digiti la password direttamente in quel terminale e {app} non la gestisce mai.",
  "settings.persistLocalHelp1": "Se attivo (predefinito), la shell e le schede Python/script di un progetto locale girano in una sessione tmux su questa macchina, così un'esecuzione lunga continua se {app} si blocca, e la scheda si ricollega al riavvio. Chiudere una scheda termina comunque la sua sessione. Richiede",
  "settings.persistLocalHelp2": "; le schede agente non sono interessate.",
  "settings.remoteFeaturesHelp": "Entrambi aggiungono un controllo a livello di macchina nell'intestazione: un tunnel OpenVPN (instrada il traffico di tutto questo computer finché è attivo) e un elenco di macchine SSH che non appartengono a nessun progetto. Disattivato per impostazione predefinita; richiesto una volta al primo avvio.",
  "settings.energyHelp": "Quando attivo, {app} rallenta per risparmiare energia: mette in pausa la rotazione inattiva del blob del progetto, calma i bagliori di stato e rallenta gli aggiornamenti in background. «A batteria» (predefinito) lo fa solo quando scollegato.",
  "settings.fastModeHelp": "Rinuncia agli aiuti che costano lavoro vero: le dimensioni delle cartelle nell'albero dei file, i punti git sulle pillole di progetto, le schede al passaggio del mouse, la lettura CPU/RAM nell'intestazione, il controllo Esegui di Python e le animazioni dell'interfaccia. Nulla viene nascosto e nulla va perso senza essere salvato: {app} dice meno, prima. Utile con un disco lento, una macchina carica o un progetto remoto su un collegamento sottile.",
  "settings.experimentalHelp1": "Funzionalità ancora in evoluzione. Ognuna è disattivata per impostazione predefinita e",
  "settings.experimentalHelpBold": "attivata per impostazione predefinita in modalità debug",
  "settings.experimentalHelp2": "— quindi compilare {app} significa vederle senza dover rispuntare questo elenco ogni volta che ne arriva una nuova. Un interruttore qui vince sempre, in entrambe le direzioni: puoi attivarne una senza la modalità debug, o disattivarne una mentre ci sei.",
  "settings.experimentalHelp3": "Disattivare una funzione che ha una propria scheda (Posta, Browser) chiude anche le schede che ha aperto: disattivata significa via, non solo nascosta dal menu di nuova scheda.",
  "settings.pythonRunHelp1": "Dà a un file",
  "settings.pythonRunHelp2": "aperto nell'editor un pulsante",
  "settings.pythonRunHelp3": "e un",
  "settings.pythonRunHelp4": "pulsante, e trasforma i suoi numeri di riga in un margine di breakpoint. Entrambi aprono una scheda terminale nel progetto — quindi girano sull'host di un progetto remoto e nel container di uno containerizzato — e usano l'interprete proprio del progetto. Il debug è",
  "settings.pythonRunHelp5": ", precaricato con i breakpoint del margine. Disattivato per impostazione predefinita perché Esegui esegue il file. Ctrl+clic su una definizione non è bloccato: legge soltanto.",
  "settings.resourceMonitorHelp": "CPU e RAM coprono l'albero dei processi proprio di {app}; GPU mostra la VRAM in uso dai modelli locali caricati in Ollama. La pillola appare nell'intestazione accanto al timer.",
  "settings.reminderHelp": "I promemoria si attivano come notifica desktop e come popup in-app che puoi posticipare. «La griglia del giorno inizia alle» imposta solo dove scorrono le viste giorno e settimana — gli eventi precedenti sono ancora lì, appena sopra.",
  "settings.zoomHelp1": "Lo zoom della finestra scala l'intera interfaccia di {app} — utile su monitor 4K / alta densità. 100% è il valore predefinito. Lo zoom è",
  "settings.zoomHelpBold": "per finestra",
  "settings.zoomHelp2": ": questo imposta la finestra principale, e ogni sottofinestra staccata mantiene il proprio. Ctrl + / Ctrl − ingrandiscono la finestra attiva e Ctrl 0 lo ripristina.",
  "settings.minSubwindowHelp": "La dimensione minima a cui una sottofinestra può essere ridotta trascinando un divisore. Predefinito {px}px se lasciato vuoto.",
  "settings.workspaceNoParking": "Questo desktop non può nascondere le finestre di altre app, quindi cambiando progetto restano sullo schermo. {app} nasconde le app di un progetto al cambio sotto X11 con KDE Plasma e Cinnamon.",
  "settings.downloadsHelp": "Cartelle scansionate dalla sezione Download del pannello laterale (il suo interruttore nella barra), per copiare rapidamente i file appena scaricati in un progetto. Sola lettura — {app} non modifica mai il percorso di download di alcun browser. Predefinita la cartella Download di sistema se vuoto.",
  "settings.removeFolderTitle": "Rimuovi questa cartella",
  "settings.dailyRecapHelp": "Un riepilogo della giornata appena conclusa: quali agenti hai usato e quanto li hai interpellati, file creati/modificati/eliminati, commit e tempo per progetto. Disattivarlo ferma il popup, non il conteggio — tutto resta locale.",

