  "remoteHosts.help":
    "La cartella in cui si apre una connessione o una navigazione per un dato host SSH, invece della directory home dell'host. Impostato una volta qui, si applica la prossima volta che ti connetti a quell'host — sia per il browser di cartelle di un nuovo progetto remoto sia per riconnettersi a uno esistente.",
  "remoteHosts.empty": "Nessun percorso standard impostato — gli host usano di default la propria directory home.",
  "remoteHosts.hostPlaceholder": "host",
  "remoteHosts.pathPlaceholder": "/percorso/sull'host",

  "agents.help1":
    "Agenti di coding IA che {app} può avviare come schede agente. Installane uno con un clic (nessun diritto da amministratore necessario), poi aggiungilo dal menu",
