  "intro.stepsLabel": "Primi passi",
  "intro.progress": "Passo {n} di {total}",
  "intro.skip": "Salta l’introduzione",
  "intro.checking": "Verifica in corso…",
  "intro.walkMeThrough": "Guidami passo passo",
  "intro.terminalNote": "I pulsanti che eseguono un comando lo aprono in una scheda terminale della console root e chiudono questa introduzione, così puoi seguirlo e rispondere alle richieste (come una password sudo). Riapri l’introduzione dal menu dell’ingranaggio → Come iniziare; torna su questa pagina.",
  "intro.page.welcome": "Benvenuto",
  "intro.page.projects": "Progetti",
  "intro.page.agents": "CLI degli agenti",
  "intro.page.localModels": "Modelli locali",
  "intro.page.askApp": "Chiedi a {app}",
  "intro.page.done": "E adesso",
  "intro.welcome.next": "Le pagine seguenti ti preparano passo passo: un progetto, una CLI di agente IA, un modello locale e la guida integrata di {app}. Ogni pagina mostra cosa è già fatto qui e ha pulsanti a un clic per il resto. Usa Avanti, oppure ← e →.",
  "intro.projects.lead": "Un progetto è una cartella che {app} gestisce come un unico spazio di lavoro: la sua pillola nell’intestazione, le sue schede e il suo layout, il suo albero dei file e la sua vista git. Cambiare pillola cambia tutto insieme, e schede e pannelli tornano dopo un riavvio.",
  "intro.projects.none": "Nessun progetto ancora",
  "intro.projects.haveSome": "{count} progetto/i aperto/i",
  "intro.projects.localTitle": "Locale",
  "intro.projects.localBody": "La cartella è su questa macchina (per impostazione predefinita in ~/{slug}/projects). Facoltativamente gira in un container Docker o in una macchina virtuale.",
  "intro.projects.remoteTitle": "Remoto (SSH)",
  "intro.projects.remoteBody": "Il progetto sta su un’altra macchina raggiungibile via SSH. Spunta Progetto remoto (SSH) in cima alla finestra Nuovo o Importa; {app} mantiene sincronizzata una copia locale.",
  "intro.projects.step1Title": "Crea o importa un progetto",
  "intro.projects.step1Body": "Nuovo progetto chiede un nome (l’unico campo obbligatorio) e crea la cartella con i file iniziali e un repository git. Importa aggiunge una cartella che hai già; Clona scarica un repository da GitHub o GitLab.",
  "intro.projects.newProject": "Nuovo progetto…",
  "intro.projects.importFolder": "Importa una cartella…",
  "intro.projects.cloneRepo": "Clona da GitHub/GitLab…",
  "intro.projects.step2Title": "Cambia con le pillole",
  "intro.projects.step2Body": "Ogni progetto ha una pillola nell’intestazione. Fai clic su una pillola per cambiare, trascinala per riordinare, clic destro per le azioni del progetto. La × chiude un progetto; resta registrato.",
  "intro.projects.step3Title": "Apri delle schede",
  "intro.projects.step3Body": "Il + nella barra delle schede di un progetto apre una shell, un visualizzatore di file o un agente IA nella cartella del progetto. Trascina una scheda sul bordo di un riquadro per dividere la vista.",
  "intro.agents.lead": "Una scheda agente esegue una CLI di programmazione IA nella cartella del progetto. {app} non le include: installa quelle che usi, una volta per macchina. Qui sotto trovi le tre più usate; Impostazioni → Gestisci CLI ne ha una trentina in più.",
  "intro.agents.registryUnavailable": "L’elenco degli agenti non è disponibile ora. Apri invece Impostazioni → Gestisci CLI.",
  "intro.agents.pick": "Scegli un agente",
  "intro.agents.step1Title": "Installa {label}",
  "intro.agents.step1Body": "Un clic esegue l’installer ufficiale del fornitore in una scheda terminale:",
  "intro.agents.install": "Installa {label} in un terminale",
  "intro.agents.noInstaller": "Non esiste un installer su una riga per questo sistema. Segui",
  "intro.agents.nodeChecking": "Ricerca di Node.js…",
  "intro.agents.nodeOk": "Node.js {version} con npm è installato.",
  "intro.agents.nodeMissing": "Questa CLI si installa con npm, che richiede Node.js {min} o successivo. Installa prima Node.js.",
  "intro.agents.installNode": "Installa Node.js in un terminale",
  "intro.agents.step2Title": "Accedi",
  "intro.agents.signIn.claude": "Al primo avvio Claude Code chiede come accedere: scegli il tuo abbonamento Claude o un account Anthropic Console e conferma nel browser. In seguito /login cambia account.",
  "intro.agents.signIn.codex": "Codex chiede di accedere: scegli Sign in with ChatGPT e conferma nel browser, oppure usa una chiave API di OpenAI.",
  "intro.agents.signIn.gemini": "Gemini chiede di accedere: scegli Login with Google e conferma nel browser, oppure usa una chiave API di Gemini.",
  "intro.agents.signInFallback": "Fallo ora in un terminale, o semplicemente nella tua prima scheda agente: chiede la stessa cosa. Se non si apre nessun browser, copia nel browser il link di accesso che la CLI stampa.",
  "intro.agents.signInNow": "Accedi ora ({command})",
  "intro.agents.signInTabLabel": "Accesso a {label}",
  "intro.agents.step3Title": "Apri una scheda agente",
  "intro.agents.step3Body": "Fai clic sulla pillola di un progetto, poi su + nella sua barra delle schede → Agenti e CLI → {label}. La scheda parte nella cartella del progetto. (Nella console root gli agenti sono disattivati finché non li attivi lì.)",
  "intro.agents.step4Title": "Invia il tuo primo prompt",
  "intro.agents.step4Body": "Scrivi una richiesta nella scheda dell’agente e premi Invio. Un buon inizio:",
  "intro.agents.examplePrompt": "Spiega la struttura di questo progetto e suggerisci un primo miglioramento.",
  "intro.agents.allClis": "Tutte le CLI degli agenti…",
  "intro.models.lead": "Ollama esegue modelli a pesi aperti su questa macchina; nulla ne esce. Un modello locale alimenta le schede agente Modello locale, il completamento automatico nell’editor e l’assistente di posta.",
