  "intro.models.step1Title": "Installa Ollama",
  "intro.models.step1Body": "Un clic esegue l’installer ufficiale in una scheda terminale. Su Linux e macOS chiede la tua password (registra un servizio di sistema); su Windows accetta la richiesta se compare.",
