  "intro.models.browse": "Sfoglia tutti i modelli…",
  "intro.models.step4Title": "Caricalo sulla GPU",
  "intro.models.step4Body": "Un modello caricato risponde subito invece di caricarsi alla prima richiesta. Resta caricato finché non lo scarichi dal menu Modelli e agenti.",
  "intro.models.loadGpu": "Carica {model} sulla GPU",
  "intro.models.reloadGpu": "Ricarica {model} sulla GPU",
  "intro.models.loading": "Caricamento…",
  "intro.models.step5Title": "Usalo in una scheda Modello locale",
  "intro.models.step5Body": "Le schede Modello locale usano il modello impostato per le schede. Poi fai clic su + nella barra delle schede di un progetto → Local Model → scegli un esecutore. Mistral (Vibe) è quello predefinito; anche Claude Code, Codex, OpenCode, Droid e OpenClaw possono pilotare un modello con strumenti.",
  "intro.models.useForTabs": "Usa {model} per le schede Modello locale",
  "intro.agents.signInExit": "«Accedi ora» avvia una sessione completa nella cartella radice di {app} (potrebbe chiedere di fidarti di quella cartella); dopo l'accesso, esci con {command}.",
  "intro.models.recommendUnknown": "Consigliato per iniziare: {model} (circa {size} GB).",
  "intro.models.vibeRunner": "Mistral (Vibe)",
  "intro.models.drivers": "Esecutori disponibili: {list}",
  "intro.models.noDrivers": "Nessun esecutore ancora installato. Installa Mistral (Vibe) per usare il modello in una scheda.",
  "intro.models.step6Title": "Facoltativo: completamento automatico",
  "intro.models.step6Body": "Apri le impostazioni del progetto nel pannello dei file → Visualizzatori nativi e spunta Completamento automatico per un tipo di file; poi premi Ctrl+Spazio nell’editor. Tab accetta, Alt+→ prende una parola, Maiusc+Tab cambia la lunghezza.",
  "intro.ask.lead": "Le schede Claude e Codex di questa macchina sono collegate alla guida integrata di {app}. Chiedi al tuo agente di {app} con parole tue — per esempio «Come sincronizzo un progetto remoto in {app}?» — e chiamerà gli strumenti {slug}-help, che cercano la risposta nella stessa guida da cui è tratta questa introduzione. Solo lettura: non cambiano mai nulla.",
  "intro.ask.statusOn": "Il server della guida è attivo",
  "intro.ask.statusOnFor": "Il server della guida è attivo per {list}",
  "intro.ask.statusOff": "Il server della guida è disattivato",
  "intro.ask.statusOldBackend": "Questa build di {app} non ha ancora il server della guida; arriva con il prossimo aggiornamento del backend.",
  "intro.ask.toggle": "Offri la guida di {app} alle schede agente",
  "intro.ask.reach": "La ricevono le schede Claude e Codex e le schede Modello locale il cui modello ha il chip MCP attivo nel menu Modelli e agenti; le altre CLI ricevono solo il suo indirizzo. Le schede che girano su un host remoto, in una VM o in un container non la raggiungono. Claude chiede di approvare lo strumento la prima volta. Le nuove schede applicano una modifica di questo interruttore; le schede aperte prima dell'aggiornamento di {app} che l'ha aggiunta non ce l'hanno.",
  "intro.ask.examplesTitle": "Cose da chiedere al tuo agente",
  "intro.ask.example1": "Come creo un progetto remoto via SSH?",
  "intro.ask.example2": "Quale modello locale va bene per la mia GPU e come lo carico?",
  "intro.ask.example3": "Come sincronizza {app} i file con una macchina remota?",
  "intro.ask.example4": "Quali scorciatoie da tastiera spostano tra i riquadri?",
  "intro.ask.tryThis": "Vedi cosa trova la guida per questo",
  "intro.ask.tryTitle": "Provalo qui",
  "intro.ask.placeholder": "Cerca nella guida di {app}…",
  "intro.ask.search": "Cerca",
  "intro.ask.noHits": "Nessun risultato. Prova altre parole.",
  "intro.ask.searchUnavailable": "La ricerca nella guida richiede il backend di {app} aggiornato.",
  "intro.done.lead": "Tutto pronto. Tutto ciò che è in queste pagine resta a portata di mano: i progetti dal + nell'intestazione, agenti e modelli locali dal + nella barra delle schede di un progetto, e le impostazioni dall'ingranaggio.",
  "intro.done.reopen": "Riapri questa introduzione quando vuoi dal menu dell’ingranaggio → Come iniziare.",
  "remoteFeatures.title": "Usi VPN o macchine remote?",
  "remoteFeatures.help": "{app} può controllare un tunnel OpenVPN e connettersi a macchine SSH su cui non hai un progetto, entrambi dall'intestazione. Entrambi sono disattivati per impostazione predefinita — attiva quello che userai. Ciascuno può essere commutato in qualsiasi momento dalle Impostazioni.",
  "remoteFeatures.continue": "Continua",
