  "pill.vmEgressOffNote": "Senza uscita di rete la VM non raggiunge nulla — le schede degli agenti cloud non funzionano; usate un modello locale o puro isolamento build/test.",
  "pill.vmMailReader": "Lettore di posta",
  "pill.vmMailReaderHelp": "Le schede agente in questa VM possono leggere gli account di posta che avete aperto agli agenti e scrivere bozze. La via d'uscita è ristretta e registrata, non sigillata: l'agente raggiunge comunque il proprio fornitore, che riceve ciò che legge. Non può mai inviare — esce solo una bozza che inviate voi. Vale dal prossimo avvio; nessun mirror, e i file scaricati da questa VM possono contenere posta.",
  "pill.vmMailReaderWide": "Un lettore di posta funziona solo con uscita Proxy e l'elenco consentito predefinito — niente GitHub, niente host aggiuntivi. Disattivate «Lettore di posta» per ampliare la rete.",
  "pill.vmAllowGithub": "Consenti github.com (clone/push)",
  "pill.vmAllowHosts": "Host aggiuntivi consentiti (uno per riga)",
  "pill.vmAllowHostsPlaceholder": "registry.npmjs.org\n.crates.io",
  "pill.vmBlockedCount": "{count} connessione/i bloccata/e — la VM ha tentato di raggiungere host fuori lista:",
  "pill.pythonInterpMenuTitle": "L'ambiente Python in cui gli script di questo progetto vengono eseguiti e debuggati. Rilevato automaticamente per impostazione predefinita (venv nell'albero, poetry, conda, pyenv); blocca un interprete quando il tuo ambiente si trova dove {app} non può dedurlo.",
  "pill.pythonInterpreterEllipsis": "Interprete Python…",
  "pill.autoConnectTitleNonHeadless": "Connette questo progetto da solo all'avvio e quando vi passi. {app} non gestisce password in questa modalità, quindi il login (e la VPN, se presente) si apre nel terminale root per autenticarti — poi il progetto si connette da solo.",
  "pill.autoConnectTitleEligible": "Connette questo progetto da solo all'avvio e quando vi passi. Non chiede mai nulla: entra direttamente quando l'host è raggiungibile, e attiva la VPN solo quando non lo è.",
  "pill.autoConnectTitleNotEligible": "Salva prima la password SSH (o usa l'autenticazione a chiave) — la connessione automatica è offerta solo quando la connessione non richiede nulla da te.",
  "pill.autoConnectOnLaunch": "Connessione automatica all'avvio",
  "pill.persistSessionsMenuTitle": "Esegue la shell remota e le schede Python/script di questo progetto all'interno di una sessione tmux sull'host, così un'esecuzione lunga continua attraverso una caduta SSH, la sospensione del laptop o la chiusura di {app} — la scheda si ricollega alla riconnessione. Chiudere una scheda termina comunque la sua sessione (con conferma). Le schede agente non sono interessate.",
  "pill.persistentSessionsTmux": "Sessioni persistenti (tmux)",
  "pill.remoteControlMenuTitle":
    "Se le schede agente Claude di questo progetto possono essere monitorate/guidate dall'app o dal web di Claude. Clicca per scorrere: usa l'impostazione globale → forza disattivato → forza attivato.",
  "pill.remoteControlInherit": "Controllo remoto (predefinito)",
  "pill.remoteControlOff": "Controllo remoto: disattivato",
  "pill.remoteControlOn": "Controllo remoto: attivato",
  "pill.remoteMachinesMenuTitle": "Aggiungi e gestisci macchine aggiuntive su cui gira questo progetto. Eseguono lo stesso codice (mantenuto in sincronizzazione unidirezionale) come worker di esperimenti in sola lettura; i loro output restano su ciascuna macchina.",
  "pill.remoteMachinesCount": "Macchine remote… ({count})",
  "pill.remoteMachinesEllipsis": "Macchine remote…",
  "pill.closeAllTabs": "Chiudi tutte le schede e finestre",
  "pill.adoptFolderLayout": "Ripristina il layout salvato nella cartella…",
  "pill.adoptFolderLayoutOk": "Ripristinate {count} scheda/e dalla cartella.",
  "pill.adoptFolderLayoutNone": "Questa cartella non contiene alcun layout salvato.",
  "pill.dangerZone": "Zona di pericolo",
  "pill.detachSshMenuTitle": "Trasforma di nuovo questo in un progetto locale. La copia di lavoro locale resta dov'è e i file dell'host remoto non vengono toccati, ma l'abbinamento viene eliminato: la sincronizzazione Git si ferma e la selezione di auto-sincronizzazione configurata per questo host viene scartata.",
  "pill.detachSshEllipsis": "Scollega host SSH…",
  "pill.removeGitMenuTitle": "Elimina la directory .git di questo progetto e tutta la cronologia di controllo versione (non può essere annullato)",
  "pill.removeGitHistoryEllipsis": "Rimuovi git e cronologia…",
  "pill.deleteProjectMenuTitle": "Disconnetti questo progetto e spostalo nell'archivio di {app}. Ripristinalo o eliminalo definitivamente più tardi dalle Impostazioni. I file di un host remoto non vengono mai toccati.",
  "pill.deleteProjectEllipsis": "Elimina progetto…",
  "pill.forgetProjectMenuTitle": "Rimuove questo progetto da {app} lasciando la cartella esattamente dov'è. Nulla nella cartella viene toccato: spariscono solo le registrazioni di {app} sul progetto. In seguito la cartella può essere importata di nuovo.",
  "pill.forgetProjectEllipsis": "Rimuovi da {app}…",
  "pill.forgetProjectTitle": "Rimuovi {name} da {app}",
  "pill.forgetDescPre": "Questo toglie",
  "pill.forgetDescMid": "dall'elenco dei progetti e scarta le registrazioni di {app} al riguardo (layout delle schede, sessioni, cronologia del tempo). La cartella",
  "pill.forgetDescPost": "viene toccata: project.json, i file di scaffold e tutto il resto restano su disco, e la cartella può essere importata di nuovo.",
  "pill.forgetRemoteNote": "L'host remoto e il mirror locale restano come sono.",
  "pill.forgetting": "Rimozione…",
  "pill.forgetProjectConfirm": "Rimuovi da {app}",
