  "remoteConnect.saveHintKeptTerminal": "conservata nel portachiavi del tuo sistema operativo — un accesso da terminale non viene visto da {app}, quindi non viene salvato nulla di nuovo; disattiva per eliminarla",
  "remoteConnect.saveHintSaved": "salvata nel portachiavi del tuo sistema operativo — disattiva per eliminarla",
  "remoteConnect.saveHintNothingTerminal": "nulla da salvare per un accesso da terminale — {app} non lo vede mai",
  "remoteConnect.autoConnectTitleEligible": "Connette questo progetto da solo all'avvio e quando vi passi. Non chiede mai nulla: entra direttamente quando l'host è raggiungibile, e attiva la VPN solo quando non lo è. Nota che attivare la VPN reindirizza tutto il traffico di questo computer — con la connessione automatica ciò avviene senza chiedere conferma, quindi tieni d'occhio l'indicatore VPN nell'intestazione.",
  "remoteConnect.autoConnectTitleNotEligible": "Salva prima la password SSH (o usa l'autenticazione a chiave) — la connessione automatica viene offerta solo quando connettersi non richiede nulla da parte tua.",
  "remoteConnect.autoConnectLabel": "Connessione automatica",
  "remoteConnect.autoConnectHintEligible": "all'avvio e al passaggio — VPN solo se l'host non è raggiungibile direttamente",
  "remoteConnect.autoConnectHintNotEligible": "richiede una password salvata o l'autenticazione a chiave",
  "remoteConnect.autoConnectVpnWarningPre": "Attenzione: se l'host non è raggiungibile direttamente, la connessione automatica attiva la VPN",
  "remoteConnect.autoConnectVpnWarningStrong": "senza chiedere",
  "remoteConnect.autoConnectVpnWarningPost": "— reindirizzando il traffico di questo computer all'avvio. L'indicatore VPN nell'intestazione mostra quando un tunnel è attivo, e può disattivarlo.",
  "remoteConnect.autoConnectInteractiveTitle": "Connette questo progetto da solo all'avvio e quando vi passi. In questa modalità {app} non gestisce alcuna password, quindi l'accesso (e la VPN, se questo progetto ne ha una) si apre nel terminale root perché tu ti autentichi — il progetto si connette da solo non appena sei entrato.",
  "remoteConnect.autoConnectInteractiveHint": "all'avvio e al passaggio — apre l'accesso nel terminale root",
