  "remoteConnect.killConfirmTitle": "Conferma: questo termina ogni sessione tmux in esecuzione sull'host — non può essere annullato.",
  "remoteConnect.killConfirmBtn": "Conferma: termina tutti i job",
  "remoteConnect.killArmTitle": "Disconnessione attiva: termina ogni job tmux in esecuzione su questo host e chiude la connessione. I job vengono terminati solo con questo clic — mai al riavvio di {app}.",
  "remoteConnect.killArmBtn": "Disconnetti e termina i job",
  "remoteConnect.forgetPasswordTitle": "Elimina la password salvata di questo host dal portachiavi del tuo sistema operativo. La connessione attuale resta attiva; la prossima connessione richiederà di nuovo la password.",
  "remoteConnect.forgetPasswordBtn": "Dimentica password salvata",
  "carefulHost.title": "Tiene il lavoro in background di {app} lontano da questa macchina: il censimento delle dimensioni dei file smette di scansionare l'host da solo, e il monitoraggio diventa più economico e lento. Usalo per un nodo di login o qualsiasi macchina condivisa con altri — non per un nodo di calcolo che tieni per la durata di un job, che è tuo finché lo hai.",
  "carefulHost.label": "Vai piano su questa macchina",
  "carefulHost.hintDefault": "per un nodo di login o una macchina condivisa: salta le scansioni che leggono l'intero filesystem",
  "usage.carefulNote":
    "Host HPC — sono elencate solo le tue sessioni e i tuoi processi. Le regole di utilizzo di un cluster non permettono di raccogliere nomi o comandi di altri utenti, quindi questo report non viene eseguito automaticamente qui.",
  "carefulHost.hintOnByDefault": "attivo per impostazione predefinita per ogni macchina remota — disattivalo se questa è tua",
  "carefulHost.hintNotCareful": "questa macchina è tua: monitoraggio completo, come in locale",
