  "machines.autoConnectAddTitle": "Connette questa macchina silenziosamente all'avvio di {app} e ogni volta che si attiva un tunnel VPN. Non chiede mai conferma — si connette solo quando l'host è raggiungibile senza password, quindi una macchina armata che non può connettersi silenziosamente resta semplicemente disattivata.",
