  "machines.hpcToggleTitle": "Contrassegna questa macchina come nodo di login condiviso di un cluster. {app} allora la legge in modo leggero (nessun nome o comando di altri utenti), non ne scansiona né misura mai il filesystem di sua iniziativa, non esegue mai sincronizzazioni di file o Git in background verso di essa, non la controlla né vi si collega a meno che tu non lo chieda, e chiede prima che qualcosa giri nella sua shell del nodo di login. Contrassegnarla ne rimuove anche il collegamento all'avvio.",
  "machines.hpcAddTitle": "Contrassegna questa macchina come nodo di login condiviso di un cluster. {app} allora la legge in modo leggero (mai nomi o righe di comando di altri utenti), non ne scansiona né misura mai il filesystem di sua iniziativa, non esegue sincronizzazioni di file o Git in background verso di essa, non la controlla né vi si collega a meno che tu non lo chieda, e chiede prima che qualcosa giri nella sua shell del nodo di login.",
  "machines.hpcBadgeTitle": "Contrassegnata come nodo di login condiviso di un cluster: lettura leggera, nessuna scansione dell'uso del disco né censimento delle cartelle, nessuna sincronizzazione di file o Git in background, nessun controllo automatico di raggiungibilità, nessun collegamento automatico silenzioso, e un avviso prima che qualcosa giri in una shell del nodo di login.",
