  "settings.agentApiNoLimit": "nessun limite mensile — le richieste sono rifiutate finché non ne imposti uno",
  "settings.agentApiUnknownModels": "Non nel listino, quindi conteggiati alla tariffa {provider} più alta: {models}",
  "settings.agentApiLedgerRestarted": "Il registro di utilizzo non era leggibile (messo da parte); il conteggio di questo mese è ripartito il {date}.",
