  "pill.agentFenceReasonSeatbelt": "sandbox-exec non disponibile",
  "pill.agentFenceMenuTitle": "Ogni scheda di agente locale di questo progetto gira nella sandbox, nella home degli agenti propria del progetto; non c'è un interruttore per spegnerla. Il lavoro fuori dalla sandbox è la sessione host della console root.",
