  "pill.agentFenceGlyphLive": "{count} scheda/e di agente di questo progetto girano fuori dalla sandbox degli agenti: sono state avviate prima che diventasse l'unica modalità. Chiudile e riaprile per metterle nella sandbox.",
  "pill.agentFenceLiveUnfenced": " · {count} scheda/e in esecuzione fuori dalla sandbox: chiudile e riaprile",
  "common.on": "attivo",
  "common.off": "disattivo",
  "hpcGuard.duScan.title": "Scansionare l’intero albero su un cluster?",
  "hpcGuard.duScan.body": "Questa operazione percorre ogni file sotto la radice del progetto per sommare le dimensioni. Su un cluster quella radice si trova di solito sul filesystem parallelo, dove un percorso ricorsivo significa una richiesta di metadati per file verso un server condiviso da tutto il centro — proprio ciò che le guide del filesystem chiedono di non fare alla leggera. È una sola scansione, non un ciclo: sta a te eseguirla se la vuoi.",
  "hpcGuard.duScan.go": "Scansiona comunque",
  "hpcGuard.census.title": "Misurare le cartelle dell’host su un cluster?",
  "hpcGuard.census.body": "Il censimento delle cartelle giganti esegue `du` sull’intero albero dell’host per trovare ciò che è troppo grande da sincronizzare. Stesso costo in metadati di una scansione completa, e questo normalmente parte da solo alla connessione — per questo qui resta disattivato se non lo chiedi.",
  "hpcGuard.census.go": "Misura comunque",
  "hpcGuard.connect.title": "Accedere a questo cluster?",
  "hpcGuard.connect.body": "Aprire questa scheda contatterebbe la macchina e vi lascerebbe un master SSH condiviso (e, per una scheda persistente, un server tmux con esso) — proprio la presenza non presidiata che l’etichetta esiste per impedire. Va bene per una scheda ripristinata al riavvio, che nessuno ha chiesto; è d’intralcio solo quando volevi davvero aprirne una. Procedere collega prima il progetto e poi apre la scheda.",
  "hpcGuard.connect.go": "Connetti e apri",
  "hpcGuard.loginNodeRun.title": "Eseguire questo sul nodo di accesso?",
  "hpcGuard.loginNodeRun.body": "Questo verrebbe eseguito sul nodo di accesso del cluster, condiviso con tutte le persone attualmente connesse. I centri chiedono di tenerne fuori il lavoro intensivo di CPU e si riservano il diritto di terminare i processi che lo caricano a lungo. La via conforme per lo stesso lavoro è un job interattivo — la shell srun della vista Job — oppure uno script batch con sbatch.",
  "hpcGuard.loginNodeRun.go": "Esegui qui comunque",
  "hpcGuard.note": "Hai etichettato questa macchina come nodo di accesso di un cluster. Rimuovi l’etichetta nel menu Macchine se era sbagliato: qui non viene ricordato nulla, quindi la domanda tornerà la prossima volta.",
  "unfencedPlatform.title": "Gli agenti su questo computer girano con tutti i tuoi permessi",
  "unfencedPlatform.body": "Windows non ha una sandbox per gli agenti. Un agente avviato qui può leggere e cambiare tutto ciò che può il tuo account: altri progetti, password salvate, chiavi SSH, il profilo del browser. Su Linux e macOS {app} tiene gli agenti in una sandbox limitata al loro progetto; qui non può.",
  "unfencedPlatform.alternative": "Accetta per avviare agenti su questo computer d'ora in poi — {app} chiede una sola volta. Preferisci un confine? Apri il progetto in un container.",
  "unfencedPlatform.accept": "Accetta e avvia",
  "unfencedPlatform.declined": "Non avviato: gli agenti su questo computer girano con tutti i tuoi permessi e questo non è stato accettato. Apri una nuova scheda agente per essere richiesto di nuovo, oppure apri il progetto in un container.",
  "passwordInput.show": "Mostra password",
  "passwordInput.hide": "Nascondi password",
  "usage.notReadHpc": "Non letto — etichettato HPC, quindi nulla lo legge senza richiesta.",
  "usage.notReadNoSession": "Non letto — nessuna sessione aperta su questa macchina.",
  "usage.readNowTitle": "Leggi questa macchina una volta, adesso.",
  "usage.readNowHpcTitle": "Leggi questa macchina una volta, adesso. È etichettata HPC, quindi nulla la legge da sé.",
  "fileError.permission": "Permesso negato — non hai accesso a questo file.",
  "fileError.remoteMissing": "Questo file non è sull’host remoto — potrebbe essere solo locale (mai sincronizzato). Passa il visualizzatore a Locale per aprirlo.",
  "fileError.missing": "Questo file non esiste più.",
  "fileError.remoteRead": "Impossibile leggere questo file dall’host remoto. Controlla la connessione e riprova.",
  "fileError.open": "Impossibile aprire questo file.",
  "startup.opening": "Apertura dello spazio di lavoro…",
  "startup.ready": "Spazio di lavoro pronto",
  "setDefaultApp.errNoProjectFile": "Questo progetto non ha un file di progetto.",
  "remoteBrowse.nameSlash": "Il nome della cartella non può contenere «/».",
